// This style of import is necessary for storybook to automatically generate the documentation for prop types and control interface
import * as React from "react";
import { LinkHTMLAttributes } from "react";
import "./ContainedTextLink.scss";
import { MpaIcon } from "../icon/MpaIcon";
import {SvgMpaIcon} from "../../assets/icons/index";
import { getIconSize } from "../utils/commonUtils";
 
// Extend existing React interface that covers all HTML HyperLink attributes
 export interface ContainedTextLinkProps extends LinkHTMLAttributes<HTMLAnchorElement> {
  /**
   * Identifying value for the HyperLink.
   */
  id: string;
    /**
   * Determines the styling of the HyperLink fontWeight: semi-bold, regular.
   */
  fontWeight?: "semi-bold" | "regular";  
  /**
   * Determines the colour palette of the HyperLink.
   */
  colour?: "primary" | "secondary" | "tertiary" | "onInverse";
  /**
   * Determines the size of the button: small, medium, large 
   */
  size?: "small" | "medium" | "large";
  /**
   * Determines the type of the hyperLink : relaxed, condensed.
   */
  textlinkType?:  "relaxed" | "condensed";
   /**
   * React icon object to be displayed before the button text.
   */
  leadingIcon?: keyof typeof SvgMpaIcon | string;
   /**
   * React icon object to be displayed after the button text.
   */
  trailingIcon?: keyof typeof SvgMpaIcon | string;
  /**
   * Determines if the button can be interacted with.
   */
  disabled?: boolean;
  /**
   * The target attribute specifies where to open the linked document.
  */
  target?: "_self" | "_blank" | "_parent" | "_top";
  /**
   * The href attribute specifies the destination URL.
   */
  href?: string;
}

const ContainedTextLink: React.FC<ContainedTextLinkProps> = ({
  id,
  fontWeight = "regular",
  size = "medium",
  textlinkType = "condensed",
  className,
  disabled = false,
  leadingIcon,
  trailingIcon,
  href,
  target = "_self",
  colour = "primary",
  ...rest
}) => {
  
  const textLinkClassName = [
    "mpa-containedLink",
    `containedLink-${size}`,
    `containedLink-${fontWeight}`,
    `containedLink-${colour}`,
    ` ${textlinkType}`,
    className,
    disabled ? "disabled" : ""
  ].filter(Boolean).join(" ");

  const iconSize = getIconSize(size);

  return (    
      <a
        id={id}
        className={textLinkClassName}
        target={target}
        href={href} 
        aria-disabled={disabled}
          {...rest}
      >
        <span className={`containedLink-span`}>
          {leadingIcon && (
            <span className={`containedLink-leadingIcon`}>
              {<MpaIcon iconName={leadingIcon} size={iconSize}/>}
            </span>
          )}
          {rest.children}
          {trailingIcon && (
            <span className={`containedLink-trailingIcon`}>              
              {<MpaIcon iconName={trailingIcon} size={iconSize}/>}
            </span>
          )}
        </span>
      </a>
  );
};

export default ContainedTextLink;
